/* The wrapper itself: strip the host's card, but NOT its width. Layout > Max width in the module
   settings (480/640/768/960/Full) is a max-width on THIS element, and the previous version of this
   rule overrode it with max-width:none!important - so picking 960 did nothing at all. */
.mf-form-wrapper:has(.mfp-fes){background:transparent!important;border:0!important;
  border-radius:0!important;box-shadow:none!important;padding:0!important}
/* The boxes INSIDE it have their own measures, and those are what squeezed the design. */
.mf-form-wrapper:has(.mfp-fes) > .mf-form-inner,
.mf-form-wrapper:has(.mfp-fes) .mf-form,
.mf-form-wrapper:has(.mfp-fes) .mf-fields-container{background:transparent!important;
  border:0!important;border-radius:0!important;box-shadow:none!important;padding:0!important;
  margin:0!important;max-width:none!important;width:100%!important}


/* megaform sets font-family on label/input/select/textarea with !important, so an authored
   <span> inside a <label> inherits the HOST typeface no matter what the shell root declares.
   Element selectors are (0,3,1) here - above megaform, below every authored class rule - and
   <i> is left alone so Font Awesome keeps its own family. */
.mfp.mfp-fes.mfp-native-generated label,.mfp.mfp-fes.mfp-native-generated span,.mfp.mfp-fes.mfp-native-generated p,.mfp.mfp-fes.mfp-native-generated div,.mfp.mfp-fes.mfp-native-generated ul,.mfp.mfp-fes.mfp-native-generated li,.mfp.mfp-fes.mfp-native-generated h1,.mfp.mfp-fes.mfp-native-generated h2,.mfp.mfp-fes.mfp-native-generated h3,.mfp.mfp-fes.mfp-native-generated button{font-family:inherit!important}
.mfp.mfp-fes.mfp-native-generated .mf-field-label{display:none!important}
/* A wizard's page-break Section renders a visible heading the mock has no room for - it exists to
   split the pages, not to be seen. */
.mfp.mfp-fes.mfp-native-generated .mf-section-break,.mfp.mfp-fes.mfp-native-generated .mf-section-title{display:none!important}
.mfp.mfp-fes.mfp-native-generated .mf-field-group{margin:0!important;width:100%}
.mfp.mfp-fes.mfp-native-generated .mf-form-title,.mfp.mfp-fes.mfp-native-generated .mf-form-description,.mfp.mfp-fes.mfp-native-generated .mf-form-actions{display:none!important}
.mfp.mfp-fes.mfp-native-generated .mf-option-item{margin:0!important}
/* megaform gives every option chip a 36px floor and paints .mf-option-icon as a rounded tile. */
.mfp.mfp-fes.mfp-native-generated .mf-option-group--chips .mf-option-check,
.mfp.mfp-fes.mfp-native-generated .mf-option-group--cards .mf-option-check{display:none!important}
