  background-image:url('/DesktopModules/MegaForm/Assets/img/festa-italiana/festa-italiana-hero.png'),url('/Modules/MegaForm/img/festa-italiana/festa-italiana-hero.png');
  background-size:cover;background-position:50% 50%;background-repeat:no-repeat}
.mfp.mfp-fes.mfp-native-generated img.fes-content-image{position:absolute!important;inset:0!important;display:block!important;
