/* nav row ----------------------------------------------------------------- */
.mfp.mfp-fes.mfp-native-generated .fes-nav{display:flex;align-items:center;justify-content:space-between;margin-top:40px;
  padding-top:24px;border-top:1px solid #ece2cf}
